performance_probe_source:
@tool
extends SceneTree
func _initialize() -> void:
	run.call_deferred()
func run() -> void:
	root.hide()
	root.size = Vector2i(1440, 900)
	await create_timer(1.0).timeout
	var base := EditorInterface.get_base_control()
	var settings := EditorInterface.get_editor_settings()
	var records := []
	for screen in ["2D", "3D"]:
		EditorInterface.set_main_screen_editor(screen)
		EditorInterface.set_distraction_free_mode(false)
		for reduced in [true, false]:
			settings.set_setting("interface/theme/reduce_transparency", reduced)
			root.propagate_notification(10000)
			await create_timer(0.3).timeout
			var panels: Array[PanelContainer] = []
			for control in base.find_children("*", "PanelContainer", true, false):
				if control.theme_type_variation == &"EditorGlassPanel":
					control.show()
					panels.append(control)
			await process_frame
			var visible := 0
			for panel in panels:
				if panel.is_visible_in_tree(): visible += 1
			var samples: Array[float] = []
			for frame in range(40):
				RenderingServer.viewport_set_active(root.get_viewport_rid(), true)
				var start := Time.get_ticks_usec()
				RenderingServer.force_draw(false)
				RenderingServer.force_sync()
				if frame >= 10: samples.append((Time.get_ticks_usec()-start)/1000.0)
			samples.sort()
			records.append({"screen":screen,"reduced_transparency":reduced,"visible_glass_panels":visible,"median_ms":samples[15],"p95_ms":samples[28],"samples":30,"viewport":"1440x900","renderer":RenderingServer.get_current_rendering_method()})
	var file := FileAccess.open(OS.get_environment("APPLE_GRAY_RENDER_OUTPUT")+"/editor-render.json",FileAccess.WRITE)
	file.store_string(JSON.stringify(records))
	quit()
